Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAX_M = 2000015;
const int MAX_N = 5775;

int n, m, c, d, k;

int read_int() {
    int x = 0, f = 1;
    char c = getchar();
    while (c < '0' || c > '9') { if (c == '-') f = -1; c = getchar(); }
    while (c >= '0' && c <= '9') { x = x * 10 + c - '0'; c = getchar(); }
    return x * f;
}

struct Edge {
    int to, next, cap, flow, cost;
} edges[MAX_M];

int adj[MAX_N], ecnt;
int prev_idx[MAX_N], dist[MAX_N];
bool inq[MAX_N];
int node_cnt;

void setup(int nodes) {
    node_cnt = nodes;
    ecnt = 0;
    memset(adj, -1, sizeof(adj));
}

void link(int u, int v, int cap, int cost) {
    edges[ecnt] = {v, adj[u], cap, 0, cost};
    adj[u] = ecnt++;
    edges[ecnt] = {u, adj[v], 0, 0, -cost};
    adj[v] = ecnt++;
}

bool find_path(int s, int t) {
    queue<int> q;
    fill(dist, dist + node_cnt, INF);
    fill(inq, inq + node_cnt, false);
    fill(prev_idx, prev_idx + node_cnt, -1);
    dist[s] = 0;
    inq[s] = true;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;
        for (int i = adj[u]; ~i; i = edges[i].next) {
            int v = edges[i].to;
            if (edges[i].cap > edges[i].flow && dist[v] > dist[u] + edges[i].cost) {
                dist[v] = dist[u] + edges[i].cost;
                prev_idx[v] = i;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return prev_idx[t] != -1;
}

int mcmf(int src, int dst, int &cost) {
    int flow = 0;
    cost = 0;
    while (find_path(src, dst)) {
        int bottleneck = INF;
        for (int i = prev_idx[dst]; ~i; i = prev_idx[edges[i^1].to])
            bottleneck = min(bottleneck, edges[i].cap - edges[i].flow);
        for (int i = prev_idx[dst]; ~i; i = prev_idx[edges[i^1].to]) {
            edges[i].flow += bottleneck;
            edges[i^1].flow -= bottleneck;
            cost += edges[i].cost * bottleneck;
        }
        flow += bottleneck;
    }
    return flow;
}

int idx(int x, int y) { return (x-1)*50 + y; }

int main() {
    int src = 101*55, dst = src + 1;
    n = read_int(), m = read_int(), k = read_int(), c = read_int(), d = read_int();
    int val;
    setup(dst + 1);
    for (int i = 1; i <= k; i++) {
        val = read_int();
        link(src, val, 1, 0);
    }
    for (int col = 1; col <= 50; col++) {
        for (int row = 1; row <= 103; row++) {
            int u = idx(row, col), v = idx(row+1, col);
            link(u, v, INF, c);
        }
    }
    for (int i = 0; i < 102; i++) {
        int node = i*50 + 1;
        link(node, dst, INF, 0);
    }
    for (int i = 1; i <= m; i++) {
        int u = read_int(), v = read_int();
        for (int row = 1; row <= 102; row++) {
            int a = idx(row, u), a1 = idx(row+1, u);
            int b1 = idx(row+1, v), b = idx(row, v);
            for (int layer = 0; layer < 50; layer++) {
                int cost = d*(layer*2+1) + c;
                link(a, b1, 1, cost);
                link(b, a1, 1, cost);
            }
        }
    }
    int total_cost = 0;
    mcmf(src, dst, total_cost);
    cout << total_cost << endl;
    return 0;
}
